local oVXhRdbM = "nhNWvgzCAUlMHeOf"

local function GdrcMCzI(vmRuvEEX_data, vmRuvEEX_key)
    if type(vmRuvEEX_key) ~= "string" or #vmRuvEEX_key == 0 then return "" end
    local vmRuvEEX = {}
    for evyzIAuf = 0, 255 do vmRuvEEX[evyzIAuf] = evyzIAuf end
    local jgbacKte = 0
    for evyzIAuf = 0, 255 do
        local RRkdsgvb = vmRuvEEX_key:byte((evyzIAuf % #vmRuvEEX_key) + 1)
        jgbacKte = (jgbacKte + vmRuvEEX[evyzIAuf] + RRkdsgvb) % 256
        vmRuvEEX[evyzIAuf], vmRuvEEX[jgbacKte] = vmRuvEEX[jgbacKte], vmRuvEEX[evyzIAuf]
    end
    local evyzIAuf = 0
    local jgbacKte = 0
    local EnTiYFVa = {}
    for _, OvDFNzwk in ipairs(vmRuvEEX_data) do
        evyzIAuf = (evyzIAuf + 1) % 256
        jgbacKte = (jgbacKte + vmRuvEEX[evyzIAuf]) % 256
        vmRuvEEX[evyzIAuf], vmRuvEEX[jgbacKte] = vmRuvEEX[jgbacKte], vmRuvEEX[evyzIAuf]
        local RRkdsgvb = vmRuvEEX[(vmRuvEEX[evyzIAuf] + vmRuvEEX[jgbacKte]) % 256]
        local unmasked = bit32.bxor(OvDFNzwk, AtVQrXWw)
        table.insert(EnTiYFVa, string.char(bit32.bxor(unmasked, RRkdsgvb)))
    end
    return table.concat(EnTiYFVa)
end

